#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h> 
#include <zephyr/input/input.h>
#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define LONG_PRESS_MS CONFIG_INPUT_LONGPRESS_TIME

static struct input_event last_events[8];
static volatile uint32_t last_events_idx;

static void test_cb(struct input_event *evt, void *user_data)
{
	uint32_t idx = last_events_idx;

	printk("test_cb: %u %x %d\n", idx, evt->code, evt->value);
	if (idx < ARRAY_SIZE(last_events)) {
		last_events[idx] = *evt;
	}
	last_events_idx = idx + 1;
}

static void clear_events(void)
{
	last_events_idx = 0;
	memset(last_events, 0, sizeof(last_events));
}

ZTEST(longpress, test_longpress_test)
{
	const struct device *const dev = DEVICE_DT_GET(DT_NODELABEL(matrix_kbd));
	const struct device *const longpress_dev = DEVICE_DT_GET(DT_NODELABEL(longpress));

	zassert_true(device_is_ready(dev));
	zassert_true(device_is_ready(longpress_dev));

	input_register_callback(longpress_dev, test_cb, NULL);

	/* Short press */
	clear_events();
	input_report_key(dev, INPUT_KEY_A, 1, true, K_FOREVER);
	input_report_key(dev, INPUT_KEY_A, 0, true, K_FOREVER);
	k_sleep(K_MSEC(100));

	zassert_equal(last_events_idx, 2, "Expected 2 events, got %d", last_events_idx);
	zassert_equal(last_events[0].code, INPUT_KEY_A);
	zassert_equal(last_events[1].code, INPUT_KEY_A);
	zassert_not_equal(last_events[0].code, INPUT_KEY_X);
	zassert_not_equal(last_events[1].code, INPUT_KEY_X);

	/* Long press */
	clear_events();
	input_report_key(dev, INPUT_KEY_B, 1, true, K_FOREVER);
	/* Wait long enough for a long press to trigger */
	k_sleep(K_MSEC(LONG_PRESS_MS + 100));
	input_report_key(dev, INPUT_KEY_B, 0, true, K_FOREVER);
	k_sleep(K_MSEC(100));

	zassert_equal(last_events_idx, 4, "Expected 4 events, got %d", last_events_idx);
	zassert_equal(last_events[0].code, INPUT_KEY_B);
	zassert_equal(last_events[1].code, INPUT_KEY_X);
	zassert_equal(last_events[2].code, INPUT_KEY_B);
	zassert_equal(last_events[3].code, INPUT_KEY_X);

	/* Short press again */
	clear_events();
	input_report_key(dev, INPUT_KEY_A, 1, true, K_FOREVER);
	input_report_key(dev, INPUT_KEY_A, 0, true, K_FOREVER);
	k_sleep(K_MSEC(100));

	zassert_equal(last_events_idx, 2, "Expected 2 events, got %d", last_events_idx);
	zassert_equal(last_events[0].code, INPUT_KEY_A);
	zassert_equal(last_events[1].code, INPUT_KEY_A);
	zassert_not_equal(last_events[0].code, INPUT_KEY_X);
	zassert_not_equal(last_events[1].code, INPUT_KEY_X);

	input_unregister_callback(longpress_dev, test_cb);
}

ZTEST_SUITE(longpress, NULL, NULL, NULL, NULL, NULL);
